from pathlib import Path
import json,hashlib,struct,collections
P=Path(__file__).resolve().parent
source=P.parent/'aaa-proof/scene.json';d=json.loads(source.read_text());lookup={a['id']:a for a in d['assets']}
base=[a['id'] for a in d['assets'] if not a['id'].startswith(('ecology-','eucalyptus-far--'))]
base.remove('habitat-terrain');base.insert(0,'habitat-terrain')
extra=['ecology-eucalyptus-mid-'+str(i) for i in range(2,7)]+['ecology-bank-rock-mid-'+str(i) for i in range(3)]+['ecology-bank-rock-near-0','ecology-grass-near-1','ecology-grass-mid-0','ecology-grass-mid-5','ecology-shrub-branches-0','ecology-shrub-leaves-0','ecology-shrub-leaves-1','ecology-shrub-leaves-2','ecology-leaf-litter-0']
ids=base+extra;assert len(ids)==len(set(ids))
assets=[lookup[id] for id in ids];vertices=sum(a['vertices'] for a in assets);assert vertices<=950000
selected=[]
for id in extra:
 g=json.loads((P/'groups'/(id+'.json')).read_text());b=Path(g['input']).read_bytes();n=struct.unpack_from('<I',b,12)[0];glb=json.loads(b[20:20+n]);selected.append({'asset_id':id,'placements':[{k:n[k] for k in ['name','translation','rotation','scale']} for n in glb['nodes']]})
excluded=[a['id'] for a in d['assets'] if a['id'] not in ids]
manifest={'schema':'webizen.bounded-native-review-selection/v1','purpose':'Campsite-led visual review within existing tangent regeneration cap; full candidate retained. This selection is not a LOD, public release or performance acceptance.','source_manifest':str(source),'source_manifest_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'asset_ids':ids,'excluded_asset_ids':excluded,'totals':{'assets':len(assets),'vertices':vertices,'triangles':sum(a['triangles'] for a in assets),'bytes':sum(a['bytes'] for a in assets),'vertex_budget':950000,'budget_headroom':950000-vertices},'camera':{'position':[-29,9.71868565242946,56],'target':[-22,5.840921689254924,27],'vertical_fov_degrees_recommended':52,'ground_height_at_camera':6.46868565242946,'native_height_evidence':'/production/aaa-environment/assets/review-camera-evaluation.json'},'composition':{'entry':'Low south approach to the camp. Gold wagon remains left of camper; solar panels form the readable front apron. Roofbox and Mini stay in view.','foreground':'Grass-mid-0 places tufts at(-29.8,48.2),(-25.8,50.5),(-27.3,47.2), ahead of the camera. Litter patches near(-22.3,43.1),(-32.7,41.5) connect this foreground to the clearing.','middle':'The six existing camp trees at(-35,19),(-24,11),(-10,16),(-38,32),(-35,44),(-18,4) retain deliberately composed side and rear silhouettes. Grass-near-1 supplies dense tufts on north/west margins; grass-mid-5 adds camp-edge clusters around(-34,28). The shrub at(-30.3,17.7) sits behind the car, not across its entry.','distance':'New mid-tree groups2–6 add30trees in the west/north woodland: a graduated backdrop behind the original6. Their x positions largely span-61.5to-16.7, z-60.9to64.7. Farther east groups do not contribute enough to this first camp composition to justify their bounded-review cost.','water':'All71native bank stones retained so alternate river/bridge review views keep an articulated bank rather than losing natural context.','destinations':'All native bridge, observatory, biology and three artwork assets retained. The review remains navigable to all current landmarks.'},'selection_rationale':[{'scope':'all non-forest baseline assets','reason':'Keep complete personal campsite, all native landmarks, actual terrain and water; never drop individual car/camper material parts.'},{'scope':'original eucalyptus-- material groups','reason':'Keep all7material groups for6near trees; selective material removal would create incomplete trees.'},{'scope':'original eucalyptus-far-- groups','reason':'Remove12broad far trees for this review because selected new west woodland now supplies the backdrop.'},{'scope':'new ecology-eucalyptus-near-0..2','reason':'Remove3additionalnear trees; original6already preserve camp framing and density.'},{'scope':'new ecology-eucalyptus-mid-2..6','reason':'Retain30 west woodland trees selected by actual authored node positions, not every-other arbitrary omission.'},{'scope':'grass-near-1,grass-mid-0,grass-mid-5','reason':'Retain47tufts including visible south-approachforeground and west/northcamp margins. Othergrassgroups largely serve distant/east views.'},{'scope':'all shrub branch and leaf groups','reason':'Keep14completeplants. Branches share one batch, so omitting a leaf batch alone would leave naked unexplained stems.'},{'scope':'all rock and litter groups','reason':'Lowvertexcost compared withfoliage; preserve riverline and ground detail.'}],'selected_native_placement_groups':selected,'required_review':['At the proposed camera, check actual grass/litter in foreground and ensure tree trunks do not obscure the vehicle or canvas.','Inspect low riverbank view for rock contact; wide litter patches still need slope contact review.','Judge native textures, shadow detail and foliage exposure from actual screenshot. Counts are not art acceptance.','If full renderer cap is fixed, keep this curated composition as a review camera; do not treat bounded profile as the complete environment.']}
(P/'assets/review-selection.json').write_text(json.dumps(manifest,indent=2),encoding='utf8')
